macro_rules! deps {
    () => {
        BorrowKind!();
        Operand!();
        BinOp!();
        CastKind!();
        UnOp!();
        AggregateKind!();
        Place!();
    };
}

macro_rules! Rvalue {
    () => {
        deps!();
        # [derive (Debug , PartialEq , Eq , Clone)] pub enum Rvalue < 'db > { # [doc = " Yields the operand unchanged"] Use (Operand < 'db >) , # [doc = " Creates an array where each element is the value of the operand."] # [doc = ""] # [doc = " Corresponds to source code like `[x; 32]`."] Repeat (Operand < 'db > , Const < 'db >) , # [doc = " Creates a reference of the indicated kind to the place."] # [doc = ""] # [doc = " There is not much to document here, because besides the obvious parts the semantics of this"] # [doc = " are essentially entirely a part of the aliasing model. There are many UCG issues discussing"] # [doc = " exactly what the behavior of this operation should be."] # [doc = ""] # [doc = " `Shallow` borrows are disallowed after drop lowering."] Ref (BorrowKind , Place < 'db >) , # [doc = " Creates a pointer/reference to the given thread local."] # [doc = ""] # [doc = " The yielded type is a `*mut T` if the static is mutable, otherwise if the static is extern a"] # [doc = " `*const T`, and if neither of those apply a `&T`."] # [doc = ""] # [doc = " **Note:** This is a runtime operation that actually executes code and is in this sense more"] # [doc = " like a function call. Also, eliminating dead stores of this rvalue causes `fn main() {}` to"] # [doc = " SIGILL for some reason that I (JakobDegen) never got a chance to look into."] # [doc = ""] # [doc = " **Needs clarification**: Are there weird additional semantics here related to the runtime"] # [doc = " nature of this operation?"] ThreadLocalRef (std :: convert :: Infallible) , # [doc = " Creates a pointer with the indicated mutability to the place."] # [doc = ""] # [doc = " This is generated by pointer casts like `&v as *const _` or raw address of expressions like"] # [doc = " `&raw v` or `addr_of!(v)`."] # [doc = ""] # [doc = " Like with references, the semantics of this operation are heavily dependent on the aliasing"] # [doc = " model."] AddressOf (std :: convert :: Infallible) , # [doc = " Yields the length of the place, as a `usize`."] # [doc = ""] # [doc = " If the type of the place is an array, this is the array length. For slices (`[T]`, not"] # [doc = " `&[T]`) this accesses the place's metadata to determine the length. This rvalue is"] # [doc = " ill-formed for places of other types."] Len (Place < 'db >) , # [doc = " Performs essentially all of the casts that can be performed via `as`."] # [doc = ""] # [doc = " This allows for casts from/to a variety of types."] # [doc = ""] # [doc = " **FIXME**: Document exactly which `CastKind`s allow which types of casts. Figure out why"] # [doc = " `ArrayToPointer` and `MutToConstPointer` are special."] Cast (CastKind , Operand < 'db > , Ty < 'db >) , # [doc = " * `Offset` has the same semantics as `pointer::offset`, except that the second"] # [doc = "   parameter may be a `usize` as well."] # [doc = " * The comparison operations accept `bool`s, `char`s, signed or unsigned integers, floats,"] # [doc = "   raw pointers, or function pointers and return a `bool`. The types of the operands must be"] # [doc = "   matching, up to the usual caveat of the lifetimes in function pointers."] # [doc = " * Left and right shift operations accept signed or unsigned integers not necessarily of the"] # [doc = "   same type and return a value of the same type as their LHS. Like in Rust, the RHS is"] # [doc = "   truncated as needed."] # [doc = " * The `Bit*` operations accept signed integers, unsigned integers, or bools with matching"] # [doc = "   types and return a value of that type."] # [doc = " * The remaining operations accept signed integers, unsigned integers, or floats with"] # [doc = "   matching types and return a value of that type."] BinaryOp (std :: convert :: Infallible) , # [doc = " Same as `BinaryOp`, but yields `(T, bool)` with a `bool` indicating an error condition."] # [doc = ""] # [doc = " When overflow checking is disabled and we are generating run-time code, the error condition"] # [doc = " is false. Otherwise, and always during CTFE, the error condition is determined as described"] # [doc = " below."] # [doc = ""] # [doc = " For addition, subtraction, and multiplication on integers the error condition is set when"] # [doc = " the infinite precision result would be unequal to the actual result."] # [doc = ""] # [doc = " For shift operations on integers the error condition is set when the value of right-hand"] # [doc = " side is greater than or equal to the number of bits in the type of the left-hand side, or"] # [doc = " when the value of right-hand side is negative."] # [doc = ""] # [doc = " Other combinations of types and operators are unsupported."] CheckedBinaryOp (BinOp , Operand < 'db > , Operand < 'db >) , # [doc = " Computes a value as described by the operation."] NullaryOp (std :: convert :: Infallible) , # [doc = " Exactly like `BinaryOp`, but less operands."] # [doc = ""] # [doc = " Also does two's-complement arithmetic. Negation requires a signed integer or a float;"] # [doc = " bitwise not requires a signed integer, unsigned integer, or bool. Both operation kinds"] # [doc = " return a value with the same type as their operand."] UnaryOp (UnOp , Operand < 'db >) , # [doc = " Computes the discriminant of the place, returning it as an integer of type"] # [doc = " [`discriminant_ty`]. Returns zero for types without discriminant."] # [doc = ""] # [doc = " The validity requirements for the underlying value are undecided for this rvalue, see"] # [doc = " [#91095]. Note too that the value of the discriminant is not the same thing as the"] # [doc = " variant index; use [`discriminant_for_variant`] to convert."] # [doc = ""] # [doc = " [`discriminant_ty`]: crate::ty::Ty::discriminant_ty"] # [doc = " [#91095]: https://github.com/rust-lang/rust/issues/91095"] # [doc = " [`discriminant_for_variant`]: crate::ty::Ty::discriminant_for_variant"] Discriminant (Place < 'db >) , # [doc = " Creates an aggregate value, like a tuple or struct."] # [doc = ""] # [doc = " This is needed because dataflow analysis needs to distinguish"] # [doc = " `dest = Foo { x: ..., y: ... }` from `dest.x = ...; dest.y = ...;` in the case that `Foo`"] # [doc = " has a destructor."] # [doc = ""] # [doc = " Disallowed after deaggregation for all aggregate kinds except `Array` and `Coroutine`. After"] # [doc = " coroutine lowering, `Coroutine` aggregate kinds are disallowed too."] Aggregate (AggregateKind < 'db > , Box < [Operand < 'db >] >) , # [doc = " Transmutes a `*mut u8` into shallow-initialized `Box<T>`."] # [doc = ""] # [doc = " This is different from a normal transmute because dataflow analysis will treat the box as"] # [doc = " initialized but its content as uninitialized. Like other pointer casts, this in general"] # [doc = " affects alias analysis."] ShallowInitBox (Operand < 'db > , Ty < 'db >) , # [doc = " NON STANDARD: allocates memory with the type's layout, and shallow init the box with the resulting pointer."] ShallowInitBoxWithAlloc (Ty < 'db >) , # [doc = " A CopyForDeref is equivalent to a read from a place at the"] # [doc = " codegen level, but is treated specially by drop elaboration. When such a read happens, it"] # [doc = " is guaranteed (via nature of the mir_opt `Derefer` in rustc_mir_transform/src/deref_separator)"] # [doc = " that the only use of the returned value is a deref operation, immediately"] # [doc = " followed by one or more projections. Drop elaboration treats this rvalue as if the"] # [doc = " read never happened and just projects further. This allows simplifying various MIR"] # [doc = " optimizations and codegen backends that previously had to handle deref operations anywhere"] # [doc = " in a place."] CopyForDeref (Place < 'db >) , }
    };
}

Rvalue!();